  color += vec3(0.30) * pow(band, 2.0) * (0.22 + 0.78 * diffuse);
  color += vec3(0.55) * specular * (0.35 + 0.65 * band);
  color += vec3(0.32) * vein * 0.12;
  color += vec3(0.18) * micro * 0.1;
